// Measured template management — extracted from mobile-bridge.js.

// --- Measured Template management ---

export const SHAPE_TO_TEMPLATE_TYPE = {
  circle: "circle", sphere: "circle", cylinder: "circle", radius: "circle",
  cone: "cone",
  cube: "rect", square: "rect",
  line: "ray", wall: "ray", ray: "ray"
};

/** dnd5e: only types in CONFIG.DND5E.areaTargetTypes need a MeasuredTemplate (see activity mixin). */
export function isAreaTargetType(type) {
  if (type == null || type === "") return false;
  const key = String(type).toLowerCase();
  const areaTypes = CONFIG?.DND5E?.areaTargetTypes;
  if (areaTypes && typeof areaTypes === "object") return key in areaTypes;
  return key in SHAPE_TO_TEMPLATE_TYPE;
}

export function iterItemActivities(sys) {
  const activities = sys?.activities;
  if (!activities) return [];
  if (typeof activities.values === "function") return [...activities.values()];
  if (Array.isArray(activities.contents)) return activities.contents;
  return Object.values(activities);
}

/**
 * Resolve area template from a dnd5e target block (activity.target or legacy system.target).
 * Matches dnd5e v4: measuredTemplate when `!!target.template.type` (activity mixin).
 */
export function resolveTargetBlockTemplate(target) {
  if (!target || typeof target !== "object") return null;

  const templateType = target.template?.type;
  if (isAreaTargetType(templateType)) {
    const size = target.template?.size ?? target.template?.width ?? target.value;
    return { type: templateType, size };
  }

  // Legacy item schema: area spells store shape in target.type + target.value.
  const legacyType = target.type;
  if (isAreaTargetType(legacyType)) {
    const size = target.value ?? target.template?.size ?? target.template?.width;
    return { type: legacyType, size };
  }

  return null;
}

export function buildTemplateSpec(type, size) {
  const grid = canvas?.grid;
  const gridDist = typeof grid?.distance === "number" && Number.isFinite(grid.distance) ? grid.distance : 5;
  const shape = String(type).toLowerCase();
  const n = Number(size);
  return {
    shape,
    size: Number.isFinite(n) && n > 0 ? n : gridDist
  };
}

/**
 * Area template shape + size when the spell/item requires MeasuredTemplate placement.
 * Returns null for single-target spells (e.g. Fire Bolt: affects.creature, empty template.type).
 */
export function resolveItemTemplateSpec(item) {
  const sys = item?.system;
  if (!sys) return null;

  for (const activity of iterItemActivities(sys)) {
    const resolved = resolveTargetBlockTemplate(activity?.target);
    if (resolved) return buildTemplateSpec(resolved.type, resolved.size);
  }

  const legacy = resolveTargetBlockTemplate(sys.target);
  if (legacy) return buildTemplateSpec(legacy.type, legacy.size);

  return null;
}

/**
 * dnd5e 3.x / 4.x: area template type + distance from the item (spell) document.
 */
export function itemMeasuredTemplateSpec(item) {
  return resolveItemTemplateSpec(item);
}

/**
 * Create a MeasuredTemplate centered on the actor's primary token (casting position).
 * `directionExplicit` — optional degrees; when omitted, uses token rotation (cone / line).
 */
export async function createMeasuredTemplateAtActorToken(user, actor, shape, size, directionExplicit, activity, item) {
  if (!canvas?.ready || !canvas.scene) throw new Error("Canvas not ready");
  const gridDist =
    typeof canvas.grid?.distance === "number" && Number.isFinite(canvas.grid.distance)
      ? canvas.grid.distance
      : 5;

  const tokenDocs = tokenDocumentsForActorOnScene(actor, canvas.scene);
  const td = tokenDocs[0];
  if (!td) throw new Error("No token on scene for this actor");

  const t = SHAPE_TO_TEMPLATE_TYPE[String(shape).toLowerCase()] ?? "circle";
  const tokenObj = td.object;
  const center = tokenObj ? tokenObj.center : { x: td.x, y: td.y };
  const dist =
    size != null && Number.isFinite(Number(size)) && Number(size) > 0 ? Number(size) : gridDist;
  const dir =
    directionExplicit !== undefined && directionExplicit !== null
      ? directionExplicit
      : (td.rotation ?? 0);

  const templateData = {
    t,
    x: center.x,
    y: center.y,
    distance: dist,
    direction: dir,
    fillColor: user.color ?? "#FF0000",
    elevation: td.elevation ?? 0,
    // Bridge runs on the GM tab; Midi-QOL refreshMeasuredTemplate checks game.user.id.
    author: game.user.id
  };
  if (t === "cone") templateData.angle = CONFIG?.MeasuredTemplate?.defaults?.angle ?? 53.13;
  if (t === "rect") {
    // For a rect, `distance` is the diagonal and `direction` its angle, so the
    // token's own rotation — usually 0 — collapsed the square into a line of
    // zero height: invisible in Foundry, and drawn as a full square by the
    // phone, which derives both sides from the distance. dnd5e builds its cube
    // AoEs the same way: side in `width`, diagonal at 45 degrees.
    templateData.width = dist;
    templateData.distance = Math.hypot(dist, dist);
    templateData.direction = 45;
  }
  applyStagingTemplateFlags(templateData, actor, td, item);

  const docs = await canvas.scene.createEmbeddedDocuments("MeasuredTemplate", [templateData]);
  return docs[0];
}

/**
 * Place a MeasuredTemplate on the canvas at a given actor's token position.
 */
export async function placeTemplate(user, payload) {
  if (!canvas?.ready || !canvas.scene) throw new Error("Canvas not ready");

  const { actorId, shape, size, direction, itemId } = payload;
  const actor = getOwnedActor(user, actorId);
  let item = null;
  let activity = null;
  if (itemId) {
    item = actor.items.get(itemId) ?? null;
    activity = item ? resolveItemAreaActivity(item) : null;
  }
  const created = await createMeasuredTemplateAtActorToken(
    user, actor, shape, size, direction, activity, item
  );
  await syncTemplateTargetsViaMidiQol(user, created, activity, actor);
  const off = canvas.grid.getOffset({ x: created.x, y: created.y });
  // Grid-correct size (the v14 compat `created.distance` is off by sceneGridSize/100).
  const geo = templateGeometry(created, regionForTemplate(created, created.parent ?? canvas.scene), canvas.grid);
  // `size` keeps its meaning (for a rect it is the DIAGONAL). `widthFt` is the
  // rect's side in scene units so the phone need not derive it from the diagonal.
  const ppu = (Number(canvas.grid?.sizeX) || Number(canvas.grid?.size) || 0) / (Number(canvas.grid?.distance) || 5);
  const widthFt =
    created.t === "rect" && ppu > 0 && geo.widthPx > 0
      ? Math.round((geo.widthPx / ppu) * 100) / 100
      : undefined;
  return {
    templateId: created.id,
    x: Math.round(created.x),
    y: Math.round(created.y),
    elevation: created.elevation ?? 0,
    shape: created.t,
    size: geo.distance,
    ...(widthFt !== undefined ? { widthFt } : {}),
    centerGridI: Math.round(Number(off.i)),
    centerGridJ: Math.round(Number(off.j))
  };
}

/**
 * Grid indices for the cell containing the template anchor point (template x/y).
 */
export function gridCenterFromTemplateDoc(templateDoc) {
  const grid = canvas?.grid;
  if (!grid || !templateDoc) return { centerGridI: null, centerGridJ: null };
  const off = grid.getOffset({ x: templateDoc.x, y: templateDoc.y });
  return {
    centerGridI: Math.round(Number(off.i)),
    centerGridJ: Math.round(Number(off.j))
  };
}

/**
 * Foundry v14 exposes MeasuredTemplate as a compatibility view over Region, but
 * its compatibility updateDocuments path skips Regions tagged core.MeasuredTemplate.
 * Update the backing Region directly there; v12/13 still use real template documents.
 */
export async function updateTemplateTransform(templateDoc, changes) {
  const scene = canvas?.scene;
  const region = scene?.regions?.get(templateDoc.id) ?? null;
  if (!region?.getFlag("core", "MeasuredTemplate")) {
    await templateDoc.update(changes);
    return scene?.templates?.get(templateDoc.id) ?? templateDoc;
  }

  const update = {};
  if (changes.x !== undefined || changes.y !== undefined || changes.direction !== undefined) {
    const shapes = region.shapes.map((shape) => shape.toObject());
    const shape = shapes[0];
    if (!shape) throw new Error("Template region has no shape");
    if (changes.x !== undefined) shape.x = changes.x;
    if (changes.y !== undefined) shape.y = changes.y;
    if (changes.direction !== undefined && shape.type !== "circle") {
      shape.rotation = changes.direction;
    }
    update.shapes = shapes;
  }
  if (changes.elevation !== undefined) {
    update["elevation.bottom"] = changes.elevation;
  }

  await region.update(update);
  return scene.templates.get(templateDoc.id) ?? templateDoc;
}

/**
 * Move a MeasuredTemplate by one grid cell in a direction, or change elevation.
 */
export async function moveTemplate(user, templateId, directionKey) {
  if (!canvas?.ready || !canvas.scene) throw new Error("Canvas not ready");
  if (!templateId) throw new Error("templateId is required");

  const templateDoc = canvas.scene.templates.get(templateId);
  if (!templateDoc) throw new Error("Template not found");

  const grid = canvas.grid;
  const gridDist = typeof grid?.distance === "number" && Number.isFinite(grid.distance) ? grid.distance : 5;
  const key = String(directionKey ?? "").toLowerCase();

  if (key === "elevate" || key === "descend") {
    const delta = key === "elevate" ? gridDist : -gridDist;
    const newElev = (templateDoc.elevation ?? 0) + delta;
    const updated = await updateTemplateTransform(templateDoc, { elevation: newElev });
    await syncTemplateTargetsViaMidiQol(user, updated, null, null);
    const g = gridCenterFromTemplateDoc(updated);
    return { templateId, x: Math.round(updated.x), y: Math.round(updated.y), elevation: newElev, ...g };
  }

  const dirConst = movementDirectionConstByKey(key);
  if (dirConst === undefined) {
    throw new Error(
      "direction must be up, down, left, right, up_left, up_right, down_left, down_right, elevate, or descend"
    );
  }

  const off = grid.getOffset({ x: templateDoc.x, y: templateDoc.y });
  const nextOff = grid.getShiftedOffset(off, dirConst);
  const center = grid.getCenterPoint(nextOff);
  const updated = await updateTemplateTransform(templateDoc, { x: center.x, y: center.y });
  await syncTemplateTargetsViaMidiQol(user, updated, null, null);
  const g = gridCenterFromTemplateDoc(updated);
  return {
    templateId,
    x: Math.round(updated.x),
    y: Math.round(updated.y),
    elevation: updated.elevation ?? 0,
    ...g
  };
}

/**
 * Checks a spell's `item.system.range` against a caster→target distance measured
 * with Foundry's own grid API (square/hex/gridless all handled by canvas.grid,
 * so this never reimplements distance math). Throws with a player-facing
 * message when the tapped cell is out of range; returns silently when allowed.
 *
 * dnd5e range units: "self", "touch", "ft"/"mi" (numeric), or "none"/"any"/"spec"/""
 * (no enforceable numeric distance — treated as unlimited, like an empty range).
 */
export function enforceTemplateRangeAtCell(item, tokenDoc, grid, targetPoint, i, j) {
  if (!item) return; // No item context (e.g. freeform template) — unlimited.

  const range = item.system?.range ?? {};
  const units = String(range.units ?? "").toLowerCase();
  const rawValue = Number(range.value);
  const hasNumericValue = Number.isFinite(rawValue) && rawValue > 0;
  const gridDist = typeof grid?.distance === "number" && Number.isFinite(grid.distance) ? grid.distance : 5;

  if (units === "self") {
    const tokenOff = grid.getOffset({ x: tokenDoc.x, y: tokenDoc.y });
    const wCells = Math.max(1, Math.round(tokenDoc.width ?? 1));
    const hCells = Math.max(1, Math.round(tokenDoc.height ?? 1));
    const withinFootprint =
      i >= tokenOff.i && i < tokenOff.i + wCells &&
      j >= tokenOff.j && j < tokenOff.j + hCells;
    if (!withinFootprint) {
      throw new Error("This spell can only target yourself (range: self)");
    }
    return;
  }

  const tokenObj = tokenDoc.object;
  const casterPoint = tokenObj ? tokenObj.center : { x: tokenDoc.x, y: tokenDoc.y };

  if (units === "touch") {
    const distance = grid.measurePath([casterPoint, targetPoint]).distance;
    if (!(distance <= gridDist + 0.01)) {
      throw new Error("Target is beyond the spell's range (touch)");
    }
    return;
  }

  if (hasNumericValue && (units === "ft" || units === "mi" || units === "")) {
    const maxDistance = units === "mi" ? rawValue * 5280 : rawValue;
    const distance = grid.measurePath([casterPoint, targetPoint]).distance;
    if (!(distance <= maxDistance + 0.01)) {
      throw new Error(`Target is beyond the spell's range (${rawValue} ${units || "ft"})`);
    }
    return;
  }

  // units is "none"/"any"/"spec"/empty with no usable numeric value: unlimited.
}

/**
 * Move an existing MeasuredTemplate to a tapped grid cell — the map's
 * tap-to-place fast path, alongside the arrow/D-pad `template.move`. The
 * target cell is constrained to the casting item's range, measured from the
 * caster's token with Foundry's grid API (see enforceTemplateRangeAtCell).
 */
export async function moveTemplateToCell(user, payload) {
  if (!canvas?.ready || !canvas.scene) throw new Error("Canvas not ready");

  const { actorId, itemId, templateId } = payload ?? {};
  if (!templateId) throw new Error("templateId is required");

  const templateDoc = canvas.scene.templates.get(templateId);
  if (!templateDoc) throw new Error("Template not found");

  // Prefer scene coordinates from a map tap (correct for square, hex and
  // gridless via Foundry's own point->offset), falling back to explicit i/j.
  let i, j;
  const sx = Number(payload?.sceneX);
  const sy = Number(payload?.sceneY);
  if (Number.isFinite(sx) && Number.isFinite(sy)) {
    // The app sends scene-relative coordinates (every position is reported to it
    // with the scene padding subtracted). Foundry's grid API works in full-canvas
    // space, so add the scene rect origin back before resolving the cell — the
    // same conversion scene.ping does. Without it the tapped point was off by the
    // padding, so the template jumped to the wrong cell (large-range circles like
    // Fireball) or fell outside range and was refused (cones like Burning Hands).
    const rect = canvas.dimensions?.sceneRect ?? { x: 0, y: 0 };
    const off = canvas.grid.getOffset({ x: sx + rect.x, y: sy + rect.y });
    i = off.i;
    j = off.j;
  } else {
    i = Math.floor(Number(payload?.i));
    j = Math.floor(Number(payload?.j));
  }
  if (!Number.isFinite(i) || !Number.isFinite(j)) {
    throw new Error("sceneX/sceneY or i/j are required");
  }

  const actor = getOwnedActor(user, actorId);
  let item = null;
  if (itemId) {
    item = actor.items.get(itemId) ?? null;
    if (!item) throw new Error("Item not found on actor");
  }

  const tokenDoc = tokenDocumentsForActorOnScene(actor, canvas.scene)[0] ?? null;
  if (!tokenDoc) throw new Error("No token on scene for this actor");

  const grid = canvas.grid;
  const target = grid.getCenterPoint({ i, j });

  enforceTemplateRangeAtCell(item, tokenDoc, grid, target, i, j);

  const updated = await updateTemplateTransform(templateDoc, { x: target.x, y: target.y });
  await syncTemplateTargetsViaMidiQol(user, updated, null, actor);
  const g = gridCenterFromTemplateDoc(updated);
  return {
    templateId,
    x: Math.round(updated.x),
    y: Math.round(updated.y),
    elevation: updated.elevation ?? 0,
    ...g
  };
}

/**
 * Rotate a MeasuredTemplate by a given angle (degrees).
 */
export async function rotateTemplate(user, templateId, angle) {
  if (!canvas?.ready || !canvas.scene) throw new Error("Canvas not ready");
  if (!templateId) throw new Error("templateId is required");

  const templateDoc = canvas.scene.templates.get(templateId);
  if (!templateDoc) throw new Error("Template not found");

  const newDir = ((templateDoc.direction ?? 0) + (angle ?? 45)) % 360;
  const updated = await updateTemplateTransform(templateDoc, { direction: newDir });
  await syncTemplateTargetsViaMidiQol(user, updated, null, null);
  const g = gridCenterFromTemplateDoc(updated);
  return { templateId, direction: updated.direction ?? newDir, ...g };
}

/**
 * Remove a MeasuredTemplate from the canvas.
 */
// A template's auto-targets are recorded (keyed by its item) every time midi-qol
// sets them — see rememberTemplateTargets in syncTemplateTargetsViaMidiQol — so
// that removing the template can un-set exactly the tokens it targeted, without
// recomputing an area that may have changed since (tokens move; the 15s post-cast
// auto-remove runs well after the targets were set).
export function rememberTemplateTargets(templateDoc, ids) {
  const itemId = bridgeFlag(templateDoc, "itemId");
  if (!itemId) return;
  const rt = bridgeRuntimeState();
  if (!rt.templateTargetsByItem) rt.templateTargetsByItem = new Map();
  rt.templateTargetsByItem.set(itemId, [...(ids ?? [])].filter(Boolean));
}

/** The last-recorded targets for an item's template, removing the record. */
export function takeTemplateTargets(itemId) {
  const map = bridgeRuntimeState().templateTargetsByItem;
  if (!itemId || !map) return [];
  const ids = map.get(itemId) ?? [];
  map.delete(itemId);
  return ids;
}

/** Drop [idsToRemove] from the user's current targets, leaving any others. */
export function clearUserTargetsByIds(user, idsToRemove) {
  if (!user || !idsToRemove?.length) return;
  const remove = new Set(idsToRemove);
  const current = [...(user.targets ?? [])].map((t) => t.id);
  const remaining = current.filter((id) => !remove.has(id));
  if (remaining.length !== current.length) applyUserTokenTargets(user, remaining);
}

export async function removeTemplate(user, templateId) {
  if (!canvas?.ready || !canvas.scene) throw new Error("Canvas not ready");
  if (!templateId) throw new Error("templateId is required");

  // A template's targets should not outlive it: un-set exactly the tokens midi-qol
  // last recorded for this template's item (looked up by the doc's item flag).
  const doc = canvas.scene.templates.get(templateId);
  const targetIds = takeTemplateTargets(bridgeFlag(doc, "itemId"));
  await canvas.scene.deleteEmbeddedDocuments("MeasuredTemplate", [templateId]);
  clearUserTargetsByIds(user, targetIds);
  return { removed: true };
}

/**
 * Delete every MeasuredTemplate belonging to a given item. Both the staging
 * (aiming) template and the finalized cast template carry
 * `flags[MODULE_ID].itemId`, so the app can auto-clear a cast area by item —
 * necessary because casting DELETES the staging template and CREATES a fresh
 * one with a new id (see the drawPreview override in useItem), which makes the
 * id the app placed with stale.
 */
export async function removeTemplatesForItem(user, payload) {
  if (!canvas?.ready || !canvas.scene) throw new Error("Canvas not ready");
  const itemId = payload?.itemId;
  if (!itemId) return { removed: 0 };
  const ids = canvas.scene.templates
    .filter((t) => bridgeFlag(t, "itemId") === itemId)
    .map((t) => t.id);
  // Un-set exactly the tokens midi-qol last recorded for this item's template.
  const targetIds = takeTemplateTargets(itemId);
  if (ids.length) {
    await canvas.scene.deleteEmbeddedDocuments("MeasuredTemplate", ids);
  }
  clearUserTargetsByIds(user, targetIds);
  return { removed: ids.length };
}

